#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=1;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
uniform shader amzt_blurBuf;
float4 amzSample_blurBuf(float2 uv) { return float4(amzt_blurBuf.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_blurBuf(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_strength;
uniform float amzp_feather;
uniform float amzp_saturation;
uniform float amzp_brightness;
uniform float amzp_gamma;
uniform float amzp_alpha;
uniform float amzp_fgAlpha;
layout(color) uniform half4 amzp_tintColor;
uniform float amzp_tintStrength;
layout(color) uniform half4 amzp_edgeColor;
uniform float amzp_edgeStrength;
uniform float amzp_scanLines;
uniform float amzp_scanLineCount;
uniform float2 amzp_fgOffset;
uniform float amzp_fgScale;
uniform float2 amzp_bgOffset;
uniform float amzp_bgScale;


        const float3 luminanceWeighting = float3(0.2126, 0.7152, 0.0722);

        float4 composite( float4 a, float4 b) {
            return a * (1. - b.a) + b;
        }

         float3x3 rgb2yuv = float3x3(
             0.299,     0.587,    0.114,
            -0.14713,  -0.28886,  0.436,
             0.615,    -0.51499, -0.10001
        );
         float3x3 yuv2rgb = float3x3(
            1.0,  0.0,      1.13983,
            1.0, -0.39465, -0.58060,
            1.0,  2.03211,  0.0
        );

        float maxComponent( float2 v ) {
            return max(v.x,v.y);
        }

        void amzRender() {

            float l2sScale = length(float4(1.,0.,0.,0.) * amzLayerToScreen());


            float2 stretchToScreenA = (1.+amzp_strength) / (abs(float4(1., 1.,0.,0.)*amzLayerToScreen()).xy);
            float2 stretchToScreenB = (1.+amzp_strength) / (abs(float4(-1., -1.,0.,0.)*amzLayerToScreen()).xy);
            float2 stretchToScreenC = (1.+amzp_strength) / (abs(float4(1., -1.,0.,0.)*amzLayerToScreen()).xy);
            float2 stretchToScreenD = (1.+amzp_strength) / (abs(float4(-1., 1.,0.,0.)*amzLayerToScreen()).xy);
            float fillScreenScale = max(max(maxComponent(stretchToScreenA),maxComponent(stretchToScreenB)), max(maxComponent(stretchToScreenC),maxComponent(stretchToScreenD)));

            float2 stFG = (amzScreenNorm() - 0.5) / amzp_fgScale + 0.5 - amzp_fgOffset/500.*float2(1.,-1.);
            float2 stBG = (amzScreenNorm() - 0.5) / amzp_bgScale + 0.5 - amzp_bgOffset/500.*float2(1.,-1.);

            float insideFG = step(0.,stFG.x) * step(stFG.x,1.) * step(0.,stFG.y) * step(stFG.y,1.);

            float4 texColor = amzTexture(0,stFG) * insideFG;
            float blurAlpha = amzTexture(1,stFG).a;
            float4 blurTexColor = amzTexture(1,(stBG-0.5)/fillScreenScale + (amzLayerCenter()/screen.zw));

            float3 tintYuv = amzp_tintColor.rgb * rgb2yuv;

            float3 rgb = blurTexColor.rgb / blurTexColor.a;
            float3 yuv = rgb * rgb2yuv;
            yuv.yz = yuv.yz * (amzp_saturation+1.0);
            yuv.yz = mix(yuv.yz,tintYuv.yz,amzp_tintStrength);
            rgb = yuv * yuv2rgb;
            rgb = clamp(pow(rgb,float3(1.0/amzp_gamma)) + float3(amzp_brightness),0.,1.);
            float4 adjBlurColor = float4(rgb,1.) * blurTexColor.a;

            adjBlurColor.rgb *= 1. - (amzp_scanLines * cos(amzScreenNorm().y*amzp_scanLineCount));

            float fa = amzp_feather < 0.0005 ? 1.0 : smoothstep(0.4999,0.5+min(0.999,amzp_feather/amzp_strength)*0.5,blurAlpha);


            amzOutput = composite(adjBlurColor*amzp_alpha,composite(amzp_edgeColor*blurAlpha*2.*amzp_edgeStrength,texColor*fa)*amzp_fgAlpha);

        }


half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

